import 'package:flutter/material.dart';
import '../models/user.dart';import '../services/api.dart';import 'auth.dart';

class AdminShell extends StatefulWidget{final User user;const AdminShell({super.key,required this.user});@override State<AdminShell> createState()=>_AdminShellState();}
class _AdminShellState extends State<AdminShell>{int tab=0;final titles=['Overview','Users','Communities','Posts','Messages','App Control'];void logout()async{await Api.logout();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const StudentLogin()),(_)=>false);}
@override Widget build(BuildContext c){final pages=[AdminOverview(),AdminUsers(),AdminCommunities(),AdminPosts(),AdminMessages(),AdminConfig()];return Scaffold(backgroundColor:const Color(0xFFF2F4F7),appBar:AppBar(backgroundColor:const Color(0xFF101828),foregroundColor:Colors.white,title:Row(children:[const Icon(Icons.shield_rounded),const SizedBox(width:10),Text('Admin • ${titles[tab]}')]),actions:[IconButton(onPressed:logout,icon:const Icon(Icons.logout))]),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard_outlined),label:'Overview'),NavigationDestination(icon:Icon(Icons.people_alt_outlined),label:'Users'),NavigationDestination(icon:Icon(Icons.groups_outlined),label:'Communities'),NavigationDestination(icon:Icon(Icons.article_outlined),label:'Posts'),NavigationDestination(icon:Icon(Icons.forum_outlined),label:'Messages'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'App')]);}}
class AdminOverview extends StatefulWidget{const AdminOverview({super.key});@override State<AdminOverview> createState()=>_AdminOverviewState();}
class _AdminOverviewState extends State<AdminOverview>{Map stats={};@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await Api.get('/admin/stats');if(mounted)setState(()=>stats=Map.from(r['stats']??{}));}catch(_){}}@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Control everything',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:5),Text('Moderate the campus from one place.',style:TextStyle(color:Colors.grey)),const SizedBox(height:20),Wrap(spacing:12,runSpacing:12,children:stats.entries.map((e)=>Container(width:155,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e.value}',style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900)),Text('${e.key}',style:TextStyle(color:Colors.grey.shade600))]))).toList()),const SizedBox(height:20),Card(color:const Color(0xFF101828),child:const Padding(padding:EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.admin_panel_settings,color:Colors.white,size:34),SizedBox(height:12),Text('Full moderation is active',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w800)),SizedBox(height:6),Text('You can disable students, delete posts, remove communities and moderate messages from the tabs below.',style:TextStyle(color:Colors.white70))])))]));}

class AdminUsers extends StatefulWidget{const AdminUsers({super.key});@override State<AdminUsers> createState()=>_AdminUsersState();}
class _AdminUsersState extends State<AdminUsers>{List users=[];String q='';@override void initState(){super.initState();load();}Future<void>load()async{final r=await Api.get('/admin/users');if(mounted)setState(()=>users=List.from(r['users']??[]));}Future<void>toggle(Map u)async{await Api.patch('/admin/users/${u['_id']}',{'active':u['active']!=true});await load();}@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(14),child:TextField(onChanged:(v)=>setState(()=>q=v.toLowerCase()),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search users'))),Expanded(child:RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:users.where((u)=>'${u['name']} ${u['email']}'.toLowerCase().contains(q)).length,itemBuilder:(c,i){final arr=users.where((u)=>'${u['name']} ${u['email']}'.toLowerCase().contains(q)).toList();final u=Map<String,dynamic>.from(arr[i]);final active=u['active']==true;return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:5),child:ListTile(leading:CircleAvatar(child:Text('${u['name']}'.trim()[0].toUpperCase())),title:Text('${u['name']}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${u['email']} • ${active?'Active':'Disabled'}'),trailing:u['role']=='admin'?const Chip(label:Text('ADMIN')):Switch(value:active,onChanged:(_)=>toggle(u)));}))) ]);}

class AdminCommunities extends StatefulWidget{const AdminCommunities({super.key});@override State<AdminCommunities> createState()=>_AdminCommunitiesState();}
class _AdminCommunitiesState extends State<AdminCommunities>{List list=[];@override void initState(){super.initState();load();}Future<void>load()async{final r=await Api.get('/admin/communities');if(mounted)setState(()=>list=List.from(r['communities']??[]));}Future<void>del(String id)async{if(!await confirmAdmin(context,'Delete community?','This also hides its posts and messages.'))return;await Api.del('/admin/communities/$id');await load();}Future<void>toggle(String id,bool active)async{await Api.patch('/admin/communities/$id',{'active':!active});await load();}@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(12),itemCount:list.length,itemBuilder:(c,i){final m=Map<String,dynamic>.from(list[i]);final active=m['active']==true;return Card(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18)),child:ListTile(title:Text('${m['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('Owner: ${m['owner'] is Map?m['owner']['name']:''}\\nMembers: ${List.from(m['members']??[]).length}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v){if(v=='delete')del('${m['_id']}');if(v=='toggle')toggle('${m['_id']}',active);},itemBuilder:(_)=>[PopupMenuItem(value:'toggle',child:Text(active?'Disable':'Enable')),const PopupMenuItem(value:'delete',child:Text('Delete community'))])));}));}

class AdminPosts extends StatefulWidget{const AdminPosts({super.key});@override State<AdminPosts> createState()=>_AdminPostsState();}
class _AdminPostsState extends State<AdminPosts>{List list=[];@override void initState(){super.initState();load();}Future<void>load()async{final r=await Api.get('/admin/posts');if(mounted)setState(()=>list=List.from(r['posts']??[]));}Future<void>del(String id)async{if(!await confirmAdmin(context,'Delete post?','Remove this post from the campus feed.'))return;await Api.del('/admin/posts/$id');await load();}@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(12),itemCount:list.length,itemBuilder:(c,i){final m=Map<String,dynamic>.from(list[i]);final a=m['author'] is Map?m['author']:{};return Card(child:ListTile(leading:const Icon(Icons.article),title:Text('${a['name']??'Student'}'),subtitle:Text('${m['text']??''}'),trailing:IconButton(onPressed:()=>del('${m['_id']}'),icon:const Icon(Icons.delete_outline)));}));}

class AdminMessages extends StatefulWidget{const AdminMessages({super.key});@override State<AdminMessages> createState()=>_AdminMessagesState();}
class _AdminMessagesState extends State<AdminMessages>{List list=[];@override void initState(){super.initState();load();}Future<void>load()async{final r=await Api.get('/admin/messages');if(mounted)setState(()=>list=List.from(r['messages']??[]));}Future<void>del(String id)async{await Api.del('/admin/messages/$id');await load();}@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(12),itemCount:list.length,itemBuilder:(c,i){final m=Map<String,dynamic>.from(list[i]);final s=m['sender'] is Map?m['sender']:{};final com=m['community'];return Card(child:ListTile(leading:const Icon(Icons.chat_bubble_outline),title:Text('${s['name']??'User'}'),subtitle:Text('${m['text']??''}\\n${com is Map?'Community: ${com['name']}':'Direct chat'}'),isThreeLine:true,trailing:IconButton(onPressed:()=>del('${m['_id']}'),icon:const Icon(Icons.delete_outline)));}));}

class AdminConfig extends StatefulWidget{const AdminConfig({super.key});@override State<AdminConfig> createState()=>_AdminConfigState();}
class _AdminConfigState extends State<AdminConfig>{final latest=TextEditingController(),minimum=TextEditingController(),apk=TextEditingController(),title=TextEditingController(),message=TextEditingController(),poster=TextEditingController(),posterTitle=TextEditingController(),posterMsg=TextEditingController();bool force=false;@override void initState(){super.initState();load();}@override void dispose(){for(final x in[latest,minimum,apk,title,message,poster,posterTitle,posterMsg])x.dispose();super.dispose();}Future<void>load()async{final r=await Api.get('/admin/config');final c=Map<String,dynamic>.from(r['config']);latest.text='${c['latestVersion']??'1.0.0'}';minimum.text='${c['minimumVersion']??'1.0.0'}';apk.text='${c['apkUrl']??''}';title.text='${c['updateTitle']??'CampusMate update'}';message.text='${c['updateMessage']??''}';poster.text='${c['homePosterUrl']??''}';posterTitle.text='${c['homePosterTitle']??''}';posterMsg.text='${c['homePosterMessage']??''}';setState(()=>force=c['forceUpdate']==true);}
Future<void>save()async{await Api.put('/admin/config',{'latestVersion':latest.text,'minimumVersion':minimum.text,'apkUrl':apk.text,'forceUpdate':force,'updateTitle':title.text,'updateMessage':message.text,'homePosterUrl':poster.text,'homePosterTitle':posterTitle.text,'homePosterMessage':posterMsg.text});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('App controls saved')));}
Widget field(TextEditingController x,String label,{int lines=1})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:x,maxLines:lines,decoration:InputDecoration(labelText:label)));
@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Remote app control',style:TextStyle(fontSize:25,fontWeight:FontWeight.w900)),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[field(latest,'Latest version'),field(minimum,'Minimum version'),field(apk,'APK download URL'),field(title,'Update title'),field(message,'Update message',lines:3),SwitchListTile(value:force,onChanged:(v)=>setState(()=>force=v),title:const Text('Force update'),subtitle:const Text('Blocks old versions below minimum version')),const SizedBox(height:8),const Divider(),const Align(alignment:Alignment.centerLeft,child:Text('Home poster',style:TextStyle(fontSize:19,fontWeight:FontWeight.w800))),const SizedBox(height:10),field(poster,'Poster image URL'),field(posterTitle,'Poster title'),field(posterMsg,'Poster message',lines:3),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Save all controls')))]))]);}
Future<bool> confirmAdmin(BuildContext c,String t,String b)async=>await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:Text(t),content:Text(b),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Delete'))]))??false;
